Definition g_tls_index : Z := 0xfe840.
Definition g_dtv_ptr : Z := 0x63fe40.            (* [comment removed for export] *)
Definition g_dtv : Z := 0x63fe68.
Definition g_dtv1 : Z := 0x63fe70.            (* [comment removed for export] *)
Definition dtv1_val : Z := 0x640648.         (* [comment removed for export] *)
Definition g_real_tls_get_addr : Z := 0xff910.
